    }
    function labelPos(e) {
      const s = byId[e.source], t = byId[e.target];
      if (e.source === 'monitoring' && e.target === 'data_platform') return [636, 718];
      if (e.source === 'monitoring' && e.target === 'training_cluster') return [910, 684];
      if (e.source === 'feature_store' && e.target === 'inference_online') return [700, 156];
      if (e.flow_type === 'lineage') {
        if (e.source === 'data_platform') return [276, 208];
        if (e.target === 'feature_store') return [488, 226];
        if (e.target === 'training_cluster') return [562, 214];
        return [696, 174];
      }
      return [(s.x + t.x)/2 + 86, (s.y + t.y)/2 + 56];
    }
    function make(tag, attrs, parent) {
      const el = document.createElementNS('http://www.w3.org/2000/svg', tag);
