        make('rect', {x:x-bw/2, y:y-20, width:bw, height:39, rx:10, class:'edge-label-bg'}, layer);
        const text = make('text', {x, y:y-3, 'text-anchor':'middle', class:'edge-label'}, layer);
        text.textContent = e.label;
        const thr = make('text', {x, y:y+12, 'text-anchor':'middle', class:'edge-throughput'}, layer);
        thr.textContent = `${e.throughput_gbps.toFixed(1)} Gbps`;
      });
    }
    function drawNodes() {
      const layer = document.getElementById('nodes');
      nodes.forEach(n => {
        const s = nodeSize(n), c = colors[n.category];
        const g = make('g', {class:'node-card', transform:`translate(${n.x},${n.y})`}, layer);
        make('rect', {width:s.w, height:s.h, class:'node-rect', fill:c.grad, stroke:c.stroke}, g);
        make('rect', {x:9, y:9, width:s.w-18, height:s.h-18, rx:14, fill:'rgba(8,13,25,0.16)', stroke:'rgba(255,255,255,0.16)'}, g);
        const lines = n.label.split('\n');
        lines.forEach((line, i) => { const tx = make('text', {x:18, y:28+i*20, class:'node-title'}, g); tx.textContent = line; });
        n.sub.slice(0,3).forEach((line, i) => { const tx = make('text', {x:18, y:70+i*15, class:'node-sub'}, g); tx.textContent = `• ${line}`; });
        make('circle', {cx:s.w-28, cy:28, r:18, class:'badge'}, g);
        make('circle', {cx:s.w-28, cy:28, r:13 + (n.criticality-7)*1.3, class:'crit-ring'}, g);
        const meta = make('text', {x:s.w-28, y:32, 'text-anchor':'middle', class:'node-meta'}, g);
        meta.textContent = n.criticality;
      });
    }
    function drawLegend() {
      const g = document.getElementById('legend');
      make('rect', {x:34, y:662, width:390, height:78, rx:18, class:'legend-card'}, g);
      const title = make('text', {x:54, y:687, class:'legend-title'}, g); title.textContent = 'Legend: node type, criticality, edge throughput';
      const items = [['#38bdf8','Data layer'],['#34d399','Compute layer'],['#f59e0b','Serving layer'],['#f87171','Observability']];
      items.forEach((it,i) => { make('circle', {cx:58+i*92, cy:714, r:7, fill:it[0]}, g); const tx=make('text',{x:70+i*92,y:718,class:'legend-text'},g); tx.textContent=it[1]; });
      make('rect', {x:452, y:662, width:484, height:78, rx:18, class:'legend-card'}, g);
      make('path', {d:'M 478 687 L 560 687', class:'edge primary', 'stroke-width':8, 'marker-end':'url(#arrowPrimary)'}, g);
      let t = make('text', {x:576, y:692, class:'legend-text'}, g); t.textContent = 'Primary data flow — thickness scales by Gbps';
      make('path', {d:'M 478 718 L 560 718', class:'edge lineage', 'stroke-width':3, 'marker-end':'url(#arrowLineage)'}, g);
      t = make('text', {x:576, y:723, class:'legend-text'}, g); t.textContent = 'Dashed lineage/version-control overlay';
      make('rect', {x:964, y:662, width:310, height:78, rx:18, class:'legend-card'}, g);
      make('path', {d:'M 990 690 C 1050 730, 1120 730, 1182 690', class:'edge feedback', 'stroke-width':4, 'marker-end':'url(#arrowFeedback)'}, g);
      t = make('text', {x:990, y:724, class:'legend-text'}, g); t.textContent = 'Feedback loop closes MLOps cycle';
      make('rect', {x:1302, y:662, width:144, height:78, rx:18, class:'legend-card'}, g);
      make('circle', {cx:1330, cy:702, r:13, fill:'none', stroke:'#ffffff', 'stroke-width':3, opacity:.45}, g);
      make('circle', {cx:1376, cy:702, r:20, fill:'none', stroke:'#ffffff', 'stroke-width':3, opacity:.45}, g);
      t = make('text', {x:1318, y:730, class:'legend-small'}, g); t.textContent = 'Node size/ring = criticality';
    }
    drawEdges(); drawNodes(); drawLegend();
    function toggleMenu() { const d = document.getElementById('vizMenuDropdown'); if (d) d.classList.toggle('open'); }
    document.addEventListener('click', e => { if (!e.target.closest('.viz-menu')) document.getElementById('vizMenuDropdown').classList.remove('open'); });
    let currentTheme = 'dark';
    function applyTheme(t) { document.documentElement.className = 'theme-' + t; currentTheme = t; document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️'; document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light'; }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    function downloadImage() {
      const node = document.getElementById('visualization');
      htmlToImage.toPng(node, {pixelRatio: 2, backgroundColor: '#070b14'}).then(function(dataUrl) {
        const a = document.createElement('a'); a.download = 'ml-infrastructure-pipeline.png'; a.href = dataUrl; a.click();
