      --text-secondary: #9fb0c8;
      --accent: #38bdf8;
      --accent-secondary: #f59e0b;
      --positive: #34d399;
      --negative: #f87171;
      --warning: #fbbf24;
      --glass-opacity: 0.08;
    }
    .theme-light {
      --bg: #f6f8fb;
      --surface: #ffffff;
      --surface-hover: #eef4ff;
      --border: #ccd7e8;
      --text: #122033;
      --text-secondary: #52657d;
      --accent: #0284c7;
      --accent-secondary: #d97706;
      --positive: #059669;
      --negative: #dc2626;
      --warning: #ca8a04;
    }
    .theme-dark {
      --bg: #070b14;
      --surface: #111827;
      --surface-hover: #18243a;
      --border: #2a3855;
      --text: #edf4ff;
      --text-secondary: #9fb0c8;
      --accent: #38bdf8;
      --accent-secondary: #f59e0b;
      --positive: #34d399;
      --negative: #f87171;
      --warning: #fbbf24;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at 18% 12%, rgba(56,189,248,0.20), transparent 32%),
        radial-gradient(circle at 80% 20%, rgba(245,158,11,0.14), transparent 28%),
        linear-gradient(135deg, #050813 0%, var(--bg) 54%, #10131e 100%);
    }
    .skip-to-content {
      position: absolute;
      left: -999px;
      top: 16px;
      background: var(--accent);
      color: #00131f;
      padding: 10px 14px;
      border-radius: 10px;
      z-index: 20;
    }
    .skip-to-content:focus { left: 16px; }
    .viz-menu {
      position: fixed;
      right: 18px;
      top: 18px;
      z-index: 30;
    }
    .viz-menu-toggle,
    .viz-menu-dropdown button {
      background: rgba(17,24,39,0.82);
      color: var(--text);
      border: 1px solid var(--border);
      border-radius: 12px;
      cursor: pointer;
      backdrop-filter: blur(12px);
    }
    .viz-menu-toggle { width: 42px; height: 42px; display: grid; place-items: center; }
    .viz-menu-dropdown {
      display: none;
      position: absolute;
      right: 0;
      top: 50px;
      width: 180px;
      padding: 8px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: rgba(8,13,25,0.92);
      box-shadow: 0 22px 60px rgba(0,0,0,0.45);
    }
    .viz-menu-dropdown.open { display: grid; gap: 6px; }
    .viz-menu-dropdown button { display: flex; gap: 8px; align-items: center; padding: 10px; width: 100%; }
    main {
      width: 1600px;
      height: 1000px;
      margin: 0 auto;
      padding: 46px 54px 40px;
    }
    .frame {
      height: 100%;
      border: 1px solid rgba(148,163,184,0.20);
      border-radius: 34px;
      background: linear-gradient(180deg, rgba(15,23,42,0.84), rgba(8,13,25,0.94));
      box-shadow: 0 32px 90px rgba(0,0,0,0.38), inset 0 1px 0 rgba(255,255,255,0.05);
      overflow: hidden;
      position: relative;
    }
    .frame::before {
      content: "";
      position: absolute;
      inset: 0;
      background-image: linear-gradient(rgba(148,163,184,0.035) 1px, transparent 1px), linear-gradient(90deg, rgba(148,163,184,0.035) 1px, transparent 1px);
      background-size: 40px 40px;
      mask-image: radial-gradient(circle at 50% 38%, black, transparent 78%);
      pointer-events: none;
    }
    header {
      position: relative;
      padding: 34px 42px 12px;
      display: flex;
      justify-content: space-between;
      gap: 28px;
      align-items: flex-start;
    }
    h1 {
      margin: 0;
      font-size: 38px;
      line-height: 1.04;
      letter-spacing: -0.04em;
      font-weight: 780;
    }
    .subtitle {
      margin: 12px 0 0;
      color: var(--text-secondary);
      font-size: 15px;
      max-width: 780px;
      line-height: 1.45;
    }
    .summary {
      display: grid;
      grid-template-columns: repeat(3, auto);
      gap: 12px;
      min-width: 430px;
    }
    .metric {
      border: 1px solid rgba(148,163,184,0.18);
      border-radius: 18px;
      padding: 14px 16px;
      background: rgba(15,23,42,0.68);
      min-width: 126px;
    }
    .metric strong { display: block; font-size: 25px; letter-spacing: -0.03em; }
    .metric span { color: var(--text-secondary); font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; }
    .chart-section { position: relative; height: 760px; margin: 0 28px 18px; }
    svg { width: 100%; height: 100%; display: block; }
    .lane-label {
      font-size: 12px;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      fill: #8ea0bd;
      font-weight: 700;
    }
    .lane-line { stroke: rgba(148,163,184,0.13); stroke-width: 1; }
    .edge.primary { stroke: #8fb4e9; }
    .edge.feedback { stroke: #f87171; }
    .edge.lineage { stroke: #c084fc; stroke-dasharray: 9 8; }
    .edge {
      fill: none;
      stroke-linecap: round;
      stroke-linejoin: round;
      filter: drop-shadow(0 0 6px rgba(148,163,184,0.18));
    }
    .edge-glow { fill: none; stroke-linecap: round; opacity: 0.16; }
    .edge-label-bg { fill: rgba(8,13,25,0.86); stroke: rgba(148,163,184,0.18); stroke-width: 1; }
    .edge-label { fill: #dbeafe; font-size: 12px; font-weight: 650; }
    .edge-throughput { fill: #9fb0c8; font-size: 11px; }
    .node-card {
      filter: drop-shadow(0 18px 28px rgba(0,0,0,0.28));
    }
    .node-rect {
      stroke-width: 2.2;
      rx: 20;
      ry: 20;
    }
    .node-title { fill: #f8fbff; font-weight: 780; font-size: 17px; letter-spacing: -0.02em; }
    .node-sub { fill: rgba(237,244,255,0.74); font-size: 11.2px; }
    .node-meta { fill: rgba(237,244,255,0.82); font-size: 11px; font-weight: 700; }
    .crit-ring { fill: none; stroke: rgba(255,255,255,0.38); stroke-width: 3; }
    .badge { fill: rgba(255,255,255,0.13); stroke: rgba(255,255,255,0.20); }
    .legend-card {
      fill: rgba(15,23,42,0.82);
      stroke: rgba(148,163,184,0.22);
      stroke-width: 1;
    }
    .legend-title { fill: #edf4ff; font-size: 14px; font-weight: 780; }
    .legend-text { fill: #b8c5d9; font-size: 12px; }
    .legend-small { fill: #8ea0bd; font-size: 10.5px; }
    .branch-zone { fill: rgba(245,158,11,0.06); stroke: rgba(245,158,11,0.22); stroke-width: 1.2; stroke-dasharray: 6 6; }
    .overlay-zone { fill: rgba(192,132,252,0.05); stroke: rgba(192,132,252,0.23); stroke-width: 1.2; stroke-dasharray: 7 7; }
    .callout-text { fill: #fef3c7; font-weight: 740; font-size: 13px; }
    .callout-sub { fill: #d7c99e; font-size: 11px; }
    .sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0; }
    @media print { .viz-menu { display: none; } body { background: #070b14; } }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-to-content">Skip to content</a>
  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>
  <main id="main-content" role="main" aria-label="ML infrastructure architecture directed graph">
    <section class="frame" id="visualization">
      <header>
        <section aria-label="Chart title and description">
          <h1>ML Infrastructure Pipeline: Directed Architecture & Closed-Loop Operations</h1>
          <p class="subtitle">Sequential flow from ingestion to monitoring, with node color encoding architecture layer, node size encoding criticality score, edge thickness encoding throughput in Gbps, and dashed lineage links as a cross-cutting overlay.</p>
        </section>
        <section class="summary" aria-label="Dataset summary metrics">
          <div class="metric"><strong>9</strong><span>System nodes</span></div>
          <div class="metric"><strong>15</strong><span>Directed edges</span></div>
          <div class="metric"><strong>45.0</strong><span>Total Gbps</span></div>
        </section>
      </header>
      <section class="chart-section" aria-label="Directed architecture chart">
        <svg id="architectureSvg" viewBox="0 0 1490 760" role="img" aria-label="ML architecture graph showing primary flow, lineage overlay, branching inference paths, and monitoring feedback loops">
          <defs>
            <marker id="arrowPrimary" markerWidth="14" markerHeight="14" refX="11" refY="5" orient="auto" markerUnits="strokeWidth">
              <path d="M0,0 L12,5 L0,10 z" fill="#8fb4e9"></path>
            </marker>
            <marker id="arrowFeedback" markerWidth="14" markerHeight="14" refX="11" refY="5" orient="auto" markerUnits="strokeWidth">
              <path d="M0,0 L12,5 L0,10 z" fill="#f87171"></path>
            </marker>
            <marker id="arrowLineage" markerWidth="14" markerHeight="14" refX="11" refY="5" orient="auto" markerUnits="strokeWidth">
              <path d="M0,0 L12,5 L0,10 z" fill="#c084fc"></path>
            </marker>
            <linearGradient id="dataGrad" x1="0" x2="1"><stop offset="0" stop-color="#0ea5e9"/><stop offset="1" stop-color="#2563eb"/></linearGradient>
            <linearGradient id="computeGrad" x1="0" x2="1"><stop offset="0" stop-color="#10b981"/><stop offset="1" stop-color="#15803d"/></linearGradient>
            <linearGradient id="servingGrad" x1="0" x2="1"><stop offset="0" stop-color="#f59e0b"/><stop offset="1" stop-color="#ea580c"/></linearGradient>
            <linearGradient id="obsGrad" x1="0" x2="1"><stop offset="0" stop-color="#ef4444"/><stop offset="1" stop-color="#b91c1c"/></linearGradient>
          </defs>
          <g id="staticLayer">
            <line class="lane-line" x1="30" y1="112" x2="1460" y2="112"/><text class="lane-label" x="34" y="98">Data layer</text>
            <line class="lane-line" x1="30" y1="302" x2="1460" y2="302"/><text class="lane-label" x="34" y="288">Compute layer</text>
            <line class="lane-line" x1="30" y1="496" x2="1460" y2="496"/><text class="lane-label" x="34" y="482">Serving layer</text>
            <line class="lane-line" x1="30" y1="654" x2="1460" y2="654"/><text class="lane-label" x="34" y="640">Observability / feedback</text>
            <rect class="branch-zone" x="875" y="350" width="338" height="220" rx="26"/>
            <text class="callout-text" x="892" y="376">Online / offline split</text>
            <text class="callout-sub" x="892" y="394">Branches at serving, converges at A/B tests</text>
            <rect class="overlay-zone" x="242" y="16" width="648" height="316" rx="28"/>
            <text class="callout-text" x="258" y="42" fill="#e9d5ff">Lineage + version-control overlay</text>
            <text class="callout-sub" x="258" y="60" fill="#d8b4fe">Dashed links cross-cut data, training, and model registry</text>
          </g>
          <g id="edges"></g>
          <g id="nodes"></g>
          <g id="legend"></g>
        </svg>
        <p class="sr-only">Data source contains nine architecture nodes with criticality scores from seven to ten and fifteen edges with throughput values from 0.1 to 12.5 Gbps.</p>
      </section>
    </section>
  </main>
  <script>
    const nodes = [
      {id:'data_platform', label:'Data Platform\n(Spark / Flink)', category:'data-layer', criticality:9, sub:['Apache Spark','Apache Flink','Kafka Ingestion'], x:128, y:92},
      {id:'feature_store', label:'Feature Store', category:'data-layer', criticality:8, sub:['Online Store (Redis)','Offline Store (Hive)','Feature Registry'], x:374, y:92},
      {id:'training_cluster', label:'Training Cluster\n(GPU)', category:'compute-layer', criticality:10, sub:['NVIDIA A100 Pool','Distributed Training','Hyperparameter Tuning'], x:622, y:246},
      {id:'model_registry', label:'Model Registry', category:'compute-layer', criticality:8, sub:['MLflow Registry','Model Versioning','Artifact Storage (S3)'], x:854, y:246},
      {id:'inference_online', label:'Inference Service\n(Online / Real-time)', category:'serving-layer', criticality:9, sub:['TensorRT','Triton Server','Load Balancer'], x:1036, y:370},
      {id:'inference_offline', label:'Inference Service\n(Offline / Batch)', category:'serving-layer', criticality:7, sub:['Spark Batch Predict','Scheduled Jobs (Airflow)'], x:1036, y:528},
      {id:'ab_experiment', label:'A/B Experiment\nPlatform', category:'serving-layer', criticality:8, sub:['Traffic Splitting','Statistical Engine','Dashboard'], x:1260, y:452},
      {id:'monitoring', label:'Monitoring &\nAlerting', category:'observability-layer', criticality:9, sub:['Prometheus','Grafana','PagerDuty','Drift Detector'], x:1260, y:620},
      {id:'version_control', label:'Version Control\n& Data Lineage', category:'observability-layer', criticality:7, sub:['DVC','Git','Lineage Graph DB'], x:374, y:246}
    ];
    const edges = [
      {source:'data_platform',target:'feature_store',flow_type:'primary',throughput_gbps:12.5,label:'Raw → Features'},
      {source:'feature_store',target:'training_cluster',flow_type:'primary',throughput_gbps:8.0,label:'Training Data'},
      {source:'training_cluster',target:'model_registry',flow_type:'primary',throughput_gbps:2.5,label:'Trained Models'},
      {source:'model_registry',target:'inference_online',flow_type:'primary',throughput_gbps:1.8,label:'Model Deploy (Online)'},
      {source:'model_registry',target:'inference_offline',flow_type:'primary',throughput_gbps:3.2,label:'Model Deploy (Batch)'},
      {source:'inference_online',target:'ab_experiment',flow_type:'primary',throughput_gbps:5.0,label:'Predictions (RT)'},
      {source:'inference_offline',target:'ab_experiment',flow_type:'primary',throughput_gbps:4.0,label:'Predictions (Batch)'},
      {source:'ab_experiment',target:'monitoring',flow_type:'primary',throughput_gbps:2.0,label:'Metrics & Results'},
      {source:'monitoring',target:'data_platform',flow_type:'feedback',throughput_gbps:0.5,label:'Data Quality Alerts'},
      {source:'monitoring',target:'training_cluster',flow_type:'feedback',throughput_gbps:0.3,label:'Retrain Trigger'},
      {source:'version_control',target:'feature_store',flow_type:'lineage',throughput_gbps:0.1,label:'Feature Versioning'},
      {source:'version_control',target:'training_cluster',flow_type:'lineage',throughput_gbps:0.1,label:'Experiment Tracking'},
      {source:'version_control',target:'model_registry',flow_type:'lineage',throughput_gbps:0.1,label:'Model Lineage'},
      {source:'data_platform',target:'version_control',flow_type:'lineage',throughput_gbps:0.2,label:'Data Lineage'},
      {source:'feature_store',target:'inference_online',flow_type:'primary',throughput_gbps:6.0,label:'Online Features'}
    ];
    const byId = Object.fromEntries(nodes.map(n => [n.id, n]));
    const colors = {
      'data-layer': {grad:'url(#dataGrad)', stroke:'#38bdf8', solid:'#38bdf8'},
      'compute-layer': {grad:'url(#computeGrad)', stroke:'#34d399', solid:'#34d399'},
      'serving-layer': {grad:'url(#servingGrad)', stroke:'#f59e0b', solid:'#f59e0b'},
      'observability-layer': {grad:'url(#obsGrad)', stroke:'#f87171', solid:'#f87171'}
    };
    function nodeSize(n) {
      const w = 174 + (n.criticality - 7) * 18;
      const h = 96 + (n.criticality - 7) * 8;
      return {w, h};
    }
    function pt(n, side) {
      const s = nodeSize(n);
      if (side === 'left') return [n.x, n.y + s.h/2];
      if (side === 'right') return [n.x + s.w, n.y + s.h/2];
      if (side === 'top') return [n.x + s.w/2, n.y];
      if (side === 'bottom') return [n.x + s.w/2, n.y + s.h];
      return [n.x + s.w/2, n.y + s.h/2];
    }
    function widthFor(t) { return 1.3 + Math.sqrt(t) * 2.55; }
    function pathFor(e) {
      const s = byId[e.source], t = byId[e.target];
      let a, b, c1, c2;
      if (e.source === 'monitoring' && e.target === 'data_platform') {
        a = pt(s,'bottom'); b = pt(t,'bottom');
        return `M ${a[0]} ${a[1]} C ${a[0]} 728, 64 728, ${b[0]} ${b[1]}`;
      }
      if (e.source === 'monitoring' && e.target === 'training_cluster') {
        a = pt(s,'left'); b = pt(t,'bottom');
        return `M ${a[0]} ${a[1]} C 988 694, 736 704, ${b[0]} ${b[1]}`;
      }
      if (e.flow_type === 'lineage') {
        if (e.source === 'data_platform') { a = pt(s,'right'); b = pt(t,'left'); return `M ${a[0]} ${a[1]} C 248 146, 260 258, ${b[0]} ${b[1]}`; }
        a = pt(s,'top');
        b = e.target === 'feature_store' ? pt(t,'bottom') : pt(t,'left');
        const lift = e.target === 'model_registry' ? -92 : -52;
        return `M ${a[0]} ${a[1]} C ${a[0]+50} ${a[1]+lift}, ${b[0]-58} ${b[1]+lift}, ${b[0]} ${b[1]}`;
      }
      if (e.source === 'ab_experiment' && e.target === 'monitoring') {
        a = pt(s,'bottom'); b = pt(t,'top'); return `M ${a[0]} ${a[1]} C ${a[0]+10} ${a[1]+44}, ${b[0]-10} ${b[1]-44}, ${b[0]} ${b[1]}`;
      }
      if (e.source === 'feature_store' && e.target === 'training_cluster') {
        a = pt(s,'right'); b = pt(t,'left'); return `M ${a[0]} ${a[1]} C ${a[0]+80} ${a[1]+16}, ${b[0]-76} ${b[1]-34}, ${b[0]} ${b[1]}`;
      }
      if (e.source === 'feature_store' && e.target === 'inference_online') {
        a = pt(s,'right'); b = pt(t,'left'); return `M ${a[0]} ${a[1]} C 650 98, 764 382, ${b[0]} ${b[1]}`;
      }
      a = pt(s,'right'); b = pt(t,'left');
      return `M ${a[0]} ${a[1]} C ${(a[0]+b[0])/2} ${a[1]}, ${(a[0]+b[0])/2} ${b[1]}, ${b[0]} ${b[1]}`;
    }
    function labelPos(e) {
      const s = byId[e.source], t = byId[e.target];
      if (e.source === 'monitoring' && e.target === 'data_platform') return [636, 718];
      if (e.source === 'monitoring' && e.target === 'training_cluster') return [910, 684];
      if (e.source === 'feature_store' && e.target === 'inference_online') return [700, 156];
      if (e.flow_type === 'lineage') {
        if (e.source === 'data_platform') return [276, 208];
        if (e.target === 'feature_store') return [488, 226];
        if (e.target === 'training_cluster') return [562, 214];
        return [696, 174];
      }
      return [(s.x + t.x)/2 + 86, (s.y + t.y)/2 + 56];
    }
    function make(tag, attrs, parent) {
      const el = document.createElementNS('http://www.w3.org/2000/svg', tag);
      Object.entries(attrs || {}).forEach(([k,v]) => el.setAttribute(k, v));
      parent.appendChild(el);
      return el;
    }
    function drawEdges() {
      const layer = document.getElementById('edges');
      edges.forEach(e => {
        const d = pathFor(e), w = widthFor(e.throughput_gbps);
        make('path', {d, class:'edge-glow', stroke: e.flow_type === 'feedback' ? '#f87171' : e.flow_type === 'lineage' ? '#c084fc' : '#93c5fd', 'stroke-width': w + 8}, layer);
        make('path', {d, class:`edge ${e.flow_type}`, 'stroke-width': w, 'marker-end': `url(#arrow${e.flow_type[0].toUpperCase()+e.flow_type.slice(1)})`}, layer);
        const [x,y] = labelPos(e);
        const bw = Math.max(92, e.label.length * 6.7 + 16);
        make('rect', {x:x-bw/2, y:y-20, width:bw, height:39, rx:10, class:'edge-label-bg'}, layer);
        const text = make('text', {x, y:y-3, 'text-anchor':'middle', class:'edge-label'}, layer);
        text.textContent = e.label;
        const thr = make('text', {x, y:y+12, 'text-anchor':'middle', class:'edge-throughput'}, layer);
        thr.textContent = `${e.throughput_gbps.toFixed(1)} Gbps`;
      });
    }
    function drawNodes() {
      const layer = document.getElementById('nodes');
      nodes.forEach(n => {
        const s = nodeSize(n), c = colors[n.category];
        const g = make('g', {class:'node-card', transform:`translate(${n.x},${n.y})`}, layer);
        make('rect', {width:s.w, height:s.h, class:'node-rect', fill:c.grad, stroke:c.stroke}, g);
        make('rect', {x:9, y:9, width:s.w-18, height:s.h-18, rx:14, fill:'rgba(8,13,25,0.16)', stroke:'rgba(255,255,255,0.16)'}, g);
        const lines = n.label.split('\n');
        lines.forEach((line, i) => { const tx = make('text', {x:18, y:28+i*20, class:'node-title'}, g); tx.textContent = line; });
        n.sub.slice(0,3).forEach((line, i) => { const tx = make('text', {x:18, y:70+i*15, class:'node-sub'}, g); tx.textContent = `• ${line}`; });
        make('circle', {cx:s.w-28, cy:28, r:18, class:'badge'}, g);
        make('circle', {cx:s.w-28, cy:28, r:13 + (n.criticality-7)*1.3, class:'crit-ring'}, g);
        const meta = make('text', {x:s.w-28, y:32, 'text-anchor':'middle', class:'node-meta'}, g);
        meta.textContent = n.criticality;
      });
    }
    function drawLegend() {
      const g = document.getElementById('legend');
      make('rect', {x:34, y:662, width:390, height:78, rx:18, class:'legend-card'}, g);
      const title = make('text', {x:54, y:687, class:'legend-title'}, g); title.textContent = 'Legend: node type, criticality, edge throughput';
      const items = [['#38bdf8','Data layer'],['#34d399','Compute layer'],['#f59e0b','Serving layer'],['#f87171','Observability']];
      items.forEach((it,i) => { make('circle', {cx:58+i*92, cy:714, r:7, fill:it[0]}, g); const tx=make('text',{x:70+i*92,y:718,class:'legend-text'},g); tx.textContent=it[1]; });
